{"args":["-lc","mkdir -p /var/www/html /var/log/nginx /etc/nginx/conf.d
echo 'Welcome to the benchmark webserver' > /var/www/html/index.html
echo 'Page not found - Please check your URL' > /var/www/html/404.html
rm -f /etc/nginx/sites-enabled/default
cat > /etc/nginx/nginx.conf <<'EOF'
user www-data;
worker_processes auto;
pid /run/nginx.pid;
error_log /var/log/nginx/benchmark-error.log;
include /etc/nginx/modules-enabled/*.conf;
events {
    worker_connections 768;
}
http {
    sendfile on;
    tcp_nopush on;
    types_hash_max_size 2048;
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    ssl_protocols TLSv1 TLSv1.1 TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;
    log_format benchmark '$remote_addr - $remote_user [$time_local] "$request_method $request_uri $server_protocol" $status $body_bytes_sent "$http_referer" "$http_user_agent"';
    limit_req_zone $binary_remote_addr zone=benchmark_zone:10m rate=10r/s;
    access_log /var/log/nginx/access.log;
    gzip on;
    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
EOF
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name localhost;
    root /var/www/html;
    index index.html;
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;
    limit_req zone=benchmark_zone burst=10 nodelay;
    error_page 404 /404.html;
    location = /404.html {
        root /var/www/html;
        internal;
    }
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
chown -R www-data:www-data /var/www/html
chmod 755 /var/www/html
touch /var/log/nginx/benchmark-access.log /var/log/nginx/benchmark-error.log
chown www-data:www-data /var/log/nginx/benchmark-access.log /var/log/nginx/benchmark-error.log
nginx -t
(pkill nginx || true; sleep 1; rm -f /run/nginx.pid; nginx; sleep 1)
nginx -t
curl -s -i http://localhost:8080/ | head -n 20
curl -s http://localhost:8080/nonexistent-$(date +%s) -o /dev/null -w "404-test:%{http_code}\n"
 sleep 1; ls -l /var/log/nginx/benchmark-access.log /var/log/nginx/benchmark-error.log; echo "--- access log tail ---"; tail -n 5 /var/log/nginx/benchmark-access.log; echo "Access logs at /var/log/nginx/benchmark-access.log"
ps aux | grep -v grep | grep nginx || ss -tlnp | grep 8080"],"command":"bash","timeout_ms":60000}

